    ("claude", "ROUTER_REAL_CLIENT_CLAUDE_VERSION"),
    ("codex", "ROUTER_REAL_CLIENT_CODEX_VERSION"),
    ("opencode", "ROUTER_REAL_CLIENT_OPENCODE_VERSION"),
];

